  IF NOT (NOT EXISTS(SELECT 1 FROM public.periods WHERE id='PER_WW1_PRELUDE') OR EXISTS(SELECT 1 FROM public.periods WHERE id='PER_WW1_PRELUDE' AND id IS NOT DISTINCT FROM 'PER_WW1_PRELUDE' AND label_fr IS NOT DISTINCT FROM 'Prélude à la Première Guerre mondiale' AND label_en IS NOT DISTINCT FROM 'Prelude to World War I' AND description_fr IS NOT DISTINCT FROM 'L’assassinat de François-Ferdinand à Sarajevo, le 28 juin 1914, déclenche une crise diplomatique. Les ultimatums et les choix des puissances conduisent à la déclaration de guerre de l’Autriche-Hongrie à la Serbie le 28 juillet.' AND description_en IS NOT DISTINCT FROM 'The assassination of Franz Ferdinand in Sarajevo on 28 June 1914 triggers a diplomatic crisis. Ultimatums and decisions by the powers lead to Austria-Hungary’s declaration of war on Serbia on 28 July.' AND start_date IS NOT DISTINCT FROM '1914-06-28T00:00:00Z' AND end_date IS NOT DISTINCT FROM '1914-07-28T00:00:00Z' AND start_years_bp IS NOT DISTINCT FROM 112.34770704996578 AND end_years_bp IS NOT DISTINCT FROM 112.26557152635182)) THEN RAISE EXCEPTION 'New period ID occupied: PER_WW1_PRELUDE'; END IF;
  IF NOT (NOT EXISTS(SELECT 1 FROM public.story_periods WHERE story_id=1 AND period_id='b34af765-32cd-4d01-820d-2934fc21c2aa') OR EXISTS(SELECT 1 FROM public.story_periods WHERE story_id=1 AND period_id='b34af765-32cd-4d01-820d-2934fc21c2aa' AND parent_period_id IS NOT DISTINCT FROM '8923819c-cc1f-4da3-8503-4a485d186b0f')) THEN RAISE EXCEPTION 'Concurrent period placement: 1/b34af765-32cd-4d01-820d-2934fc21c2aa'; END IF;
